  if (error instanceof SoundboardPlanChangedError) status = "plan-changed"
  if (error instanceof AutoModerationPlanChangedError) status = "plan-changed"
  if (error instanceof ScheduledEventPlanChangedError) status = "plan-changed"
  if (error instanceof StageInstancePlanChangedError) status = "plan-changed"
  if (error instanceof ChannelPermissionOverwritePlanChangedError) status = "plan-changed"
  if (error instanceof ChannelPermissionSyncPlanChangedError) status = "plan-changed"
  if (error instanceof RoleCreationPlanChangedError) status = "plan-changed"
  if (error instanceof RoleConfigurationPlanChangedError) status = "plan-changed"
  if (error instanceof RoleOrderingPlanChangedError) status = "plan-changed"
  if (error instanceof ChannelClonePlanChangedError) status = "plan-changed"
  if (error instanceof ChannelDeletionPlanChangedError) status = "plan-changed"
  if (error instanceof RoleDeletionPlanChangedError) status = "plan-changed"
  if (error instanceof ChannelOrderingPlanChangedError) status = "plan-changed"
  if (error instanceof MemberNicknamePlanChangedError) status = "plan-changed"
  if (error instanceof MemberVerificationPlanChangedError) status = "plan-changed"
  if (error instanceof MemberRolePlanChangedError) status = "plan-changed"
  if (error instanceof MemberVoicePlanChangedError) status = "plan-changed"
  if (error instanceof PollPlanChangedError) status = "plan-changed"
  if (error instanceof WebhookMessagePlanChangedError) status = "plan-changed"
  if (error instanceof InteractionNotificationPlanChangedError) status = "plan-changed"
  if (error instanceof DeletionOperationConflictError) status = "operation-key-conflict"
  if (error instanceof ChannelCreationOperationConflictError) status = "operation-key-conflict"
  if (error instanceof ChannelMetadataOperationConflictError) status = "operation-key-conflict"
  if (error instanceof VoiceChannelStatusOperationConflictError) {
    status = "operation-key-conflict"
  }
  if (error instanceof ForumTagOperationConflictError) status = "operation-key-conflict"
  if (error instanceof AttachmentMessageOperationConflictError) status = "operation-key-conflict"
  if (error instanceof ComponentMessageOperationConflictError) status = "operation-key-conflict"
